def dados_gif_simulados():
    """Decodifica apenas na abertura da cena cinematográfica."""
    dados = base64.b85decode(_GIF_B85)
    if hashlib.sha256(dados).hexdigest() != GIF_SHA256:
        raise ValueError("GIF de Simulados não passou na verificação de integridade")
    return dados
